/** A local yyyy-mm-dd (toISOString is UTC, which turns an evening's "tomorrow" into today east of Greenwich and today into tomorrow west of it). */
const isoDay = (d: Date) => d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
const dayLabel = (iso: string) => { try { return new Date(iso + "T12:00:00").toLocaleDateString(DLOCALE, { weekday: "short", month: "short", day: "numeric" }); } catch (_e) { return iso; } };
/* SORT YOUR CREWS (owner 2026-11-18): one order for the Quick view rows and the cards under it, so the number on a row is the number on its card. "Default" is the order App hands the crews in. The pick outlives a tab switch (the view unmounts) in a module variable; it is a view preference, not saved anywhere. */
type CrewSortKey = "default" | "soon" | "ready" | "name";
const CREW_SORTS: ReadonlyArray<[CrewSortKey, string]> = [["default", "Default order"], ["soon", "Soonest day"], ["ready", "Ready first"], ["name", "Name (A to Z)"]];
let lastCrewSort: CrewSortKey = "default";
/* PAST CREWS, SORTED AND FILTERED (owner 2026-11-19: "you can sort and filter to find the correct past crews to start a new one"). Archived is one of the filters: it was a dropdown at the foot of the page. */
type PastSortKey = "recent" | "oldest" | "name";
const PAST_SORTS: ReadonlyArray<[PastSortKey, string]> = [["recent", "Most recent"], ["oldest", "Oldest first"], ["name", "Place (A to Z)"]];
type PastFilterKey = "all" | "climbed" | "open" | "archived";
/** How far a log with no crew on it may sit from a past crew's day and still be that crew's climb: a trip moved a few days earlier, or a week later. */
const PAST_LOG_DAYS_BEFORE = 3;
const PAST_LOG_DAYS_AFTER = 7;
/** Who the climb picker is opened for: past crewmates ("Climb with them again") or one friend ("Start a crew with a friend"). */
interface CrewAgainFor { key: string; mates: CrewListViewPerson[]; routeId: CrewListViewId | null; title?: string; subtitle?: string; sharedIds?: ReadonlyArray<string> }
/** The saved climbs that picker offers: never the climb the past crew just did, and the climbs you BOTH saved first, under their own heading, each climb once. */
function againPicks(picks: ReadonlyArray<CrewListViewPickGroup>, a: CrewAgainFor): CrewListViewPickGroup[] {
  const base = picks.map(g => ({ ...g, rs: g.rs.filter(r => r.id !== a.routeId) }));
  const first = a.sharedIds || [];
  const all = base.flatMap(g => g.rs);
  const top = first.map(id => all.find(r => r.id === id)).filter((r): r is CrewListViewRoute => !!r);
  const rest = top.length ? base.map(g => ({ ...g, rs: g.rs.filter(r => !first.includes(r.id)) })) : base;
  return (top.length ? [{ list: { id: "__shared", name: "You both want" }, rs: top }] : []).concat(rest).filter(g => g.rs.length);
}
/** The days put forward for a crew, as agreedDate and the card read them: `dates`, else the single `date`. */
const crewDays = (cr: CrewListViewCrew): ReadonlyArray<string> => (cr.dates && cr.dates.length ? cr.dates : cr.date ? [cr.date] : []);
/** The day a crew has SETTLED on, by the card's own rule (crewStage): the day everyone agreed, or the one the organiser locked. Found signed in (2026-11-18): a locked crew's card read "Locked in: Tue, Nov 24" over a row still saying "3 days proposed". */
const crewSetDay = (cr: CrewListViewCrew): string | null => (agreedDate(cr) as string | null) || (cr.date && cr.dateForced ? cr.date : null);
/** The day a crew is heading for: the settled day, else the earliest day still ahead that anyone put forward. */
const crewDay = (cr: CrewListViewCrew): string | null => { const ad = crewSetDay(cr); if (ad) return ad; const today = isoDay(new Date()); const ds = crewDays(cr).filter(d => d >= today).slice().sort(); return ds[0] || null; };
function sortCrews(list: ReadonlyArray<CrewListViewCrew>, key: CrewSortKey, nameOf: (cr: CrewListViewCrew) => string, readyOf: (cr: CrewListViewCrew) => boolean): CrewListViewCrew[] {
  const rows = list.map((cr, i) => ({ cr, i }));
  if (key === "soon") rows.sort((a, b) => { const x = crewDay(a.cr), y = crewDay(b.cr); return x === y ? a.i - b.i : !x ? 1 : !y ? -1 : x < y ? -1 : 1; });
  else if (key === "ready") rows.sort((a, b) => (readyOf(b.cr) ? 1 : 0) - (readyOf(a.cr) ? 1 : 0) || a.i - b.i);
  else if (key === "name") rows.sort((a, b) => (nameOf(a.cr) ? 0 : 1) - (nameOf(b.cr) ? 0 : 1) || nameOf(a.cr).localeCompare(nameOf(b.cr), undefined, { sensitivity: "base", numeric: true }) || a.i - b.i);
  return rows.map(x => x.cr);
}
/** What a Quick view row says about the place beyond its name: grade (the one the card header prints, crewPlace's), discipline and pitches, then the area it is in. Only stored values; a part that is missing is left out. */
function crewPlaceFacts(p: CrewListViewPlace): { facts: string; where: string } {
  const disc = p.disc ? ((CAT[p.disc] || {}).label || "") : "";
  const r = p.kind === "route" ? p.route : null;
  const n = r ? Number(r.pitches) : 0;
  const facts = [r ? (p.grade || "") : "", disc ? (p.kind === "area" ? disc + " session" : disc) : "", n > 1 ? n + " pitches" : ""].filter(Boolean).join(" · ");
  const a = r && r._dbArea ? r._dbArea : null;
  const where = [p.parentName, a && a.parentName, a && a.region].filter((x, i, all): x is string => !!x && x !== p.name && all.indexOf(x) === i).join(" · ");
  return { facts, where };
}
/** POST AN OPEN CREW (batch B item 17; polished 2026-11-14 on owner ask "polish it"): the form read as a bare dropdown, a raw "mm/dd/yyyy" box and Post. Now each field is labelled, the climbs are grouped by the list they were saved to (as + Create a crew groups them), the day is the next two weekends as one-tap chips with "Other day…" for the picker, and a line says what Post will make before it is pressed. */
function QuickOpenCrew({ picks, activeCrews, formCrew }: { picks: ReadonlyArray<CrewListViewPickGroup>; activeCrews: ReadonlyArray<{ routeId?: string | null }>; formCrew: CrewListViewProps["formCrew"] }) {
  const [rid, setRid] = useState("");
  const [day, setDay] = useState("");
  const [other, setOther] = useState(false);
  const now = new Date();
  const min = isoDay(new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1));
  /* The next two weekends, counted from tomorrow (a crew posted today for today has no one to join it). */
  const chips: string[] = [];
  for (let i = 1; chips.length < 4 && i < 16; i++) { const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() + i); if (d.getDay() === 6 || d.getDay() === 0) chips.push(isoDay(d)); }
  const free = picks.map(g => ({ list: g.list, rs: g.rs.filter(r => !activeCrews.some(c => c.routeId === r.id)) })).filter(g => g.rs.length);
  const route = rid ? free.flatMap(g => g.rs).find(r => r.id === rid) : null;
  const ok = !!route && !!day && day >= min;
  const lbl = { fontSize: 12, fontWeight: 700, color: C.textSub, marginBottom: 6 };
  const field = { width: "100%", minHeight: 40, boxSizing: "border-box" as const, padding: "0 10px", borderRadius: 10, border: "1px solid " + C.field, background: C.surface, color: C.text, fontSize: 13, fontFamily: "inherit", minWidth: 0 };
  const pill = (on: boolean) => ({ minHeight: 36, padding: "7px 13px", borderRadius: 20, border: "1px solid " + (on ? C.blue : C.border), background: on ? C.blueBg : C.surface, color: on ? C.onSolid : C.textSub, fontSize: 13, fontWeight: 700, fontFamily: "inherit", cursor: "pointer", whiteSpace: "nowrap" as const });
  const custom = !!day && !chips.includes(day);
  const box = { marginTop: 12, padding: "12px 14px", background: C.card, border: "1px solid " + C.border, borderRadius: 12 };
  const head = <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 0.5, textTransform: "uppercase" as const, color: C.label, marginBottom: 4 }}>Post an open crew</div>;
  if (!free.length) return <div style={box}>{head}<div style={{ fontSize: 12, color: C.textMuted, lineHeight: 1.45 }}>Every saved climb already has a crew. Save another climb to post one.</div></div>;
  return <form onSubmit={e => { e.preventDefault(); if (!ok) return; formCrew(rid, [], { date: day }); setRid(""); setDay(""); setOther(false); }} aria-label="Post an open crew" style={box}>
    {head}
    <div style={{ fontSize: 12, color: C.textMuted, lineHeight: 1.45, marginBottom: 12 }}>Pick a climb and a day. Any climber can find the crew under Join a crew and ask to come.</div>
    <label style={{ display: "block", marginBottom: 12 }}><div style={lbl}>Climb</div>
      <select value={rid} onChange={e => setRid(e.target.value)} style={{ ...field, color: rid ? C.text : C.textMuted }}><option value="">Choose a saved climb</option>{free.map(g => <optgroup key={g.list.id} label={g.list.name}>{g.rs.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}</optgroup>)}</select>
    </label>
    <div role="group" aria-label="Day" style={{ marginBottom: 12 }}><div style={lbl}>Day</div>
      <div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}>
        {chips.map(d => <button key={d} type="button" aria-pressed={day === d} onClick={() => { setDay(d); setOther(false); }} style={pill(day === d)}>{dayLabel(d)}</button>)}
        <button type="button" aria-pressed={other || custom} onClick={() => { setOther(true); if (!custom) setDay(""); }} style={pill(other || custom)}>{custom ? dayLabel(day) : "Other day…"}</button>
      </div>
      {other || custom ? <input type="date" aria-label="Other day" value={custom ? day : ""} min={min} onChange={e => setDay(e.target.value)} style={{ ...field, maxWidth: 220, marginTop: 8 }} /> : null}
    </div>
    <div style={{ display: "flex", alignItems: "center", gap: 12, paddingTop: 10, borderTop: "1px solid " + C.border }}>
      <div aria-live="polite" style={{ flex: 1, minWidth: 0, fontSize: 12.5, color: ok ? C.text : C.textMuted, lineHeight: 1.4, overflowWrap: "anywhere" }}>{ok && route ? <>Posts <b>{route.name}</b> on <b>{dayLabel(day)}</b>, open to joiners.</> : !route ? "Choose a climb to post." : "Choose a day to post."}</div>
      <button type="submit" disabled={!ok} style={{ flexShrink: 0, minHeight: 40, padding: "0 18px", borderRadius: 10, border: "1px solid " + (ok ? C.actionSolid : C.border), background: ok ? C.actionSolid : C.surface,boxShadow:(ok)?SOLID_LEDGE(C):"none", color: ok ? C.onSolid : C.textMuted, fontSize: 13, fontWeight: 700, fontFamily: "inherit", cursor: ok ? "pointer" : "default", whiteSpace: "nowrap" }}>Post crew</button>
    </div>
  </form>;
}

